from produire import produire,paras,steps,table
parts=[
('L’{hémorragie sous-conjonctivale} est une accumulation de sang sous la conjonctive. Elle résulte de la rupture d’un petit vaisseau conjonctival ou épiscléral. Une forme isolée habituelle ne diminue pas la vision.',paras('La conjonctive transparente laisse voir une nappe rouge sur le blanc de l’œil. Le sang est à la surface externe du globe, contrairement à un hyphéma dans la chambre antérieure ou à une hémorragie du vitré.', 'L’aspect peut être impressionnant sans traduire une atteinte visuelle grave. Cette interprétation rassurante n’est valable qu’après vérification de la vision, de la douleur, du contexte et de l’absence de traumatisme préoccupant.')),
('Le {contexte recherche un déclencheur et des récidives}. De nombreux épisodes sont spontanés. Traumatisme mineur, hypertension ou traitement antithrombotique peuvent favoriser le saignement.',paras('Le College décrit davantage de formes idiopathiques après cinquante ans et de causes traumatiques chez les adultes plus jeunes. Ce sont des tendances de contexte, pas une estimation de fréquence suisse.', 'Toux, effort ou manœuvre de Valsalva peuvent précéder l’apparition. Les traitements anticoagulants ou antiagrégants et les troubles hémorragiques sont à rechercher, sans attribuer automatiquement tout épisode à un médicament.')),
('Le {mécanisme est celui d’un saignement superficiel}. Le sang diffuse sous une membrane transparente. Sa résorption progressive explique les changements de couleur.',paras('La rupture d’un vaisseau ne signifie pas que la rétine saigne. L’étendue rouge visible et la gravité fonctionnelle ne sont pas équivalentes ; une petite lésion douloureuse ou traumatique peut être plus préoccupante.', 'La couleur peut évoluer comme celle d’une ecchymose. L’évolution attendue doit être mise en relation avec la disparition progressive, sans utiliser la couleur seule pour dater précisément le début.')),
('Le {tri exclut une plaie et une autre cause de rougeur}. Un traumatisme impose une évaluation ophtalmologique urgente selon les HUG. Douleur, photophobie ou baisse visuelle sont atypiques pour une forme simple.',paras('Après projection à grande vitesse, choc important ou corps étranger suspect, ne pas se rassurer sur le seul aspect de la nappe. Si une plaie du globe est possible, protéger sans compression, éviter la pression sur l’œil et organiser immédiatement l’évaluation.', 'Une douleur profonde ou une rougeur avec cornée anormale oriente vers un autre diagnostic. Des saignements extraoculaires, un malaise ou un trouble général nécessitent aussi une évaluation de leur gravité.')),
('L’{anamnèse précise le caractère isolé ou répété}. Demander traumatisme, frottement, lentilles et effort récent. Rechercher médicaments et autres manifestations hémorragiques.',paras('Noter début, unilatéralité ou bilatéralité et épisodes antérieurs. Interroger sur épistaxis, saignement gingival, ecchymoses inhabituelles ou saignement digestif selon le contexte.', 'Relever le nom et la dose des traitements antithrombotiques, les modifications récentes et les interactions possibles. Un anticoagulant ne doit pas être arrêté par le patient sur la seule découverte d’une nappe rouge indolore.')),
('L’{examen confirme une nappe superficielle sans déficit visuel}. Mesurer la vision et examiner cornée et pupille. Contrôler la pression artérielle.',paras('La forme habituelle est localisée, sans sécrétion purulente et sans inflammation intraoculaire apparente. Une gêne légère est possible, mais une douleur nette ou une baisse visuelle oblige à revoir l’hypothèse.', 'Rechercher lésion de surface, corps étranger et signes de traumatisme selon le mécanisme. L’examen complet doit être adapté au risque ; ne pas exercer de pression si une rupture du globe est suspectée.')),
('L’{approche syndromique distingue saignement et inflammation}. Une nappe rouge indolore diffère d’une rougeur vasculaire diffuse. Le contexte détermine la suite du bilan.',table(['Tableau','Orientation'],[['Nappe isolée, vision conservée, pas de traumatisme.','Hémorragie sous-conjonctivale simple probable.'],['Après traumatisme ou corps étranger.','Évaluation urgente de l’intégrité oculaire.'],['Récidives, bilatéralité ou autres saignements.','Rechercher trouble de coagulation, thrombopénie ou facteur systémique.'],['Douleur profonde, photophobie ou vision diminuée.','Rechercher notamment kératite, uvéite, sclérite ou fermeture d’angle.'],['Sang dans la chambre antérieure.','Hyphéma : autre localisation et autre prise en charge.']])) ,
('Le {diagnostic positif est clinique dans une forme typique}. La nappe sous-conjonctivale explique la couleur rouge. La vision conservée et l’absence d’alarme soutiennent le caractère simple.',paras('Aucun test biologique n’est nécessaire pour prouver que la nappe visible contient du sang. En revanche, un examen incomplet ne permet pas d’exclure une lésion associée, particulièrement après traumatisme.', 'La localisation superficielle doit être distinguée des autres hémorragies de l’œil. La réassurance vient après ce diagnostic positif et l’évaluation du contexte, non avant.')),
('Les {examens complémentaires dépendent du contexte}. La pression artérielle est contrôlée même lors d’un épisode unique. Récidive ou bilatéralité justifient un bilan hémorragique ciblé.',paras('Les HUG recommandent un contrôle de la crase et des thrombocytes pour les formes récidivantes ou bilatérales. La numération et les tests de coagulation sont interprétés avec l’histoire, les traitements et les autres saignements.', 'Sous antivitamine K, le contrôle de l’INR répond à la question du niveau d’anticoagulation. Un INR normal ne mesure pas l’effet de tous les anticoagulants ; choisir l’évaluation avec le prescripteur selon la molécule et la situation. Un bilan uniforme de tous les patients n’est pas déduit de ces recommandations.')),
('L’{algorithme associe exclusion du danger et suivi}. Une forme non traumatique simple relève surtout d’explications. Une évolution atypique déclenche une réévaluation.',steps('Vérifier vision, douleur, cornée et mécanisme traumatique.', 'Orienter en urgence si traumatisme préoccupant ou signe incompatible avec une forme simple.', 'Contrôler la pression artérielle, rechercher médicaments et autres saignements.', 'En cas de récidive ou de bilatéralité, organiser le bilan ciblé de coagulation et des thrombocytes.', 'Expliquer la résorption spontanée et les motifs de consultation ; adresser si absence de résorption à trois semaines.')),
('La {prise en charge suisse est généralement conservatrice}. Aucun antibiotique n’accélère la résorption d’un saignement isolé. Expliquer l’évolution et traiter une cause générale identifiée.',paras('Les HUG décrivent une résorption en deux à trois semaines ; le résumé européen parle habituellement d’une à deux semaines. Ces délais décrivent une évolution variable, pas une garantie individuelle.', 'Une lubrification adaptée peut soulager une gêne de surface sans accélérer l’élimination du sang. En l’absence de gêne, aucun collyre n’est nécessaire ; le sang ne doit pas être drainé par le patient.', 'Ne pas interrompre seul un anticoagulant ou un antiagrégant. Si un excès d’anticoagulation ou un saignement plus important est suspecté, le prescripteur évalue le risque hémorragique et thrombotique et décide des mesures nécessaires.', 'À trois semaines sans résorption, les HUG recommandent de rechercher une pathologie sous-jacente et d’adresser au spécialiste. Consulter plus tôt si douleur, baisse visuelle, nouvelle extension préoccupante ou autre saignement.')),
('La {prévention vise les facteurs identifiés}. Éviter les frottements et revoir la manipulation des lentilles si elle est en cause. Contrôler une hypertension et réévaluer les traitements avec leur prescripteur.',paras('Une mesure tensionnelle élevée doit être interprétée et suivie dans le parcours approprié ; la seule nappe rouge ne définit pas une urgence hypertensive. Les symptômes généraux et l’atteinte d’organes guident cette évaluation.', 'Une récidive ne doit pas conduire à une automédication par collyres vasoconstricteurs ou corticoïdes. Rechercher le déclencheur, vérifier l’absence d’autres saignements et conserver la liste exacte des médicaments.')),
('Le {point clé} est de confirmer une forme superficielle sans alarme avant de rassurer. Vision normale et absence de douleur sont attendues. Traumatisme, récidive ou persistance changent la conduite.',paras('Une hémorragie sous-conjonctivale typique guérit généralement spontanément. L’enjeu est d’éviter à la fois un traitement oculaire inutile et la méconnaissance d’une lésion traumatique ou d’un trouble général.'))]
quiz=[('La nappe rouge siège-t-elle habituellement dans la rétine ?','Non, sous la conjonctive.'),('La vision est-elle normalement diminuée dans une forme simple ?','Non.'),('L’aspect impressionnant suffit-il à établir la gravité ?','Non, le contexte et la fonction visuelle comptent.'),('Quel contrôle général est recommandé même pour un premier épisode ?','La pression artérielle.'),('Que change un traumatisme ?','Il impose une évaluation urgente pour exclure une lésion associée.'),('Une douleur profonde est-elle typique ?','Non, rechercher une autre cause.'),('Quels signes rechercher hors de l’œil ?','D’autres saignements ou ecchymoses inhabituelles.'),('Quel bilan les HUG proposent-ils en cas de récidive ou de bilatéralité ?','Contrôle de la crase et des thrombocytes, adapté au contexte.'),('L’INR évalue-t-il tous les anticoagulants ?','Non.'),('Faut-il arrêter seul un anticoagulant ?','Non, la décision relève d’une évaluation avec le prescripteur.'),('Un antibiotique accélère-t-il la disparition du sang isolé ?','Non.'),('Quel délai de résorption les HUG décrivent-ils ?','Deux à trois semaines, avec variabilité individuelle.'),('Que faire si la nappe ne se résorbe pas à trois semaines ?','Rechercher une cause sous-jacente et adresser au spécialiste.'),('Faut-il attendre ce délai si la vision baisse ?','Non, réévaluer en urgence.')]
produire(6,parts,quiz,(1,17,23))
